282	  /// Spend the offer, then type the picker command into this pane and run it.
283	  ///
284	  /// `consume` removes the offer BEFORE returning the command, so this cannot fire twice — a
285	  /// double-click, or SwiftUI evaluating the action again, would otherwise each start a billed agent
286	  /// session. A nil return is the button already being spent, not an error.
287	  private func resume(_ backend: AgentBackend) {
288	    guard let invocation = resumeCoordinator.consume(tab: tabID, backend: backend) else { return }
289	    state?.view.sendCommandLine(invocation.commandLine)
290	  }
